-- Gifts sent with reactivity letters. Sale-only keepsakes: no use, no
-- stats, sold to a vendor. Bind on pickup keeps them out of the auction
-- house and away from auction bots. Rare from raids, Uncommon otherwise.
--
-- Entries 7770000-7770098 sit in a block reserved for this module, far
-- above the stock range. The bridge checks the names at startup and
-- skips a gift whose entry holds something else.
DELETE FROM `item_template` WHERE `entry` BETWEEN 7770000 AND 7770098;
INSERT INTO `item_template`
    (`entry`, `class`, `subclass`, `name`, `displayid`, `Quality`,
     `BuyCount`, `BuyPrice`, `SellPrice`, `bonding`, `description`,
     `stackable`, `maxcount`, `Material`)
VALUES
(7770000, 15, 0, 'Searing Blade Badge', 51512, 2, 1, 0, 5000, 1, 'A blackened iron badge worn by the Searing Blade cultists. The Kor''kron count them to know how many are left.', 1, 0, 4),
(7770001, 15, 0, 'Deadmines Gold Nugget', 41755, 2, 1, 0, 7000, 1, 'Before the First War, the Deadmines were the richest gold mines in Stormwind. This nugget came from a vein the Defias never found.', 1, 0, 4),
(7770002, 15, 0, 'Silverlaine Family Signet', 31905, 2, 1, 0, 9000, 1, 'A signet bearing the crest of Baron Silverlaine, the keep''s lord before Arugal came. The family is gone, but a collector would still pay for it.', 1, 0, 4),
(7770003, 15, 0, 'Moonlit Temple Shell', 4362, 2, 1, 0, 10000, 1, 'A pale shell from the steps of the sunken temple of Elune. It shimmers faintly in moonlight.', 1, 0, 4),
(7770004, 15, 0, 'Confiscated Lockpick Set', 16453, 2, 1, 0, 10000, 1, 'A roll of fine Defias lockpicks taken from a cell after the riot. Useless to an honest citizen, but a merchant will buy the steel.', 1, 0, 4),
(7770005, 15, 0, 'Agamaggan''s Thorn', 19497, 2, 1, 0, 12000, 1, 'A thorn from the great vines of the Razorfen, which the quilboar say sprang from the blood of the demigod Agamaggan. Collectors pay well for them.', 1, 0, 4),
(7770006, 15, 0, 'Frost-Withered Thornvine', 941, 2, 1, 0, 20000, 1, 'A length of the Razorfen''s great thorn vine, blackened by the lich''s cold. Quilboar shamans would trade a lot to have it back.', 1, 0, 4),
(7770007, 15, 0, 'Scarlet Monastery Hymnal', 3154, 2, 1, 0, 25000, 1, 'A prayer book from the monastery library, older than the Crusade. Its margins are full of a monk''s careful notes.', 1, 0, 4),
(7770008, 15, 0, 'Sandfury Bone Fetish', 5920, 2, 1, 0, 40000, 1, 'A troll fetish of bone and feathers taken from Zul''Farrak. Tran''rek says it''s harmless now. He wouldn''t keep it himself.', 1, 0, 4),
(7770009, 15, 0, 'Vial of Pristine Maraudon Water', 51756, 2, 1, 0, 45000, 1, 'Water drawn from the pools near Zaetar''s resting place, clear again now that the princess is gone.', 1, 0, 4),
(7770010, 15, 0, 'Shed Emerald Dragonscale', 21363, 2, 1, 0, 50000, 1, 'A small green scale shed by one of Itharius''s flight. It is cool to the touch and smells of rain.', 1, 0, 4),
(7770011, 15, 0, 'Scarshield Legion Insignia', 31899, 2, 1, 0, 60000, 1, 'The insignia of one of the Dark Horde''s legions in Blackrock Spire. Its owner won''t miss it.', 1, 0, 4),
(7770012, 15, 0, 'Caer Darrow Lake Pearl', 16209, 2, 1, 0, 80000, 1, 'A black pearl from the lake around Caer Darrow. Eva says the fishermen used to find them before the Cult came.', 1, 0, 4),
(7770013, 15, 0, 'Tarnished Silver Hand Badge', 35274, 2, 1, 0, 90000, 1, 'A badge of the Order of the Silver Hand, which was founded in Stratholme, found in the ruins.', 1, 0, 4),
(7770014, 15, 0, 'Blackhand Legion Seal', 43407, 2, 1, 0, 80000, 1, 'The seal of the Blackhand Legion, the Dark Horde''s elite. Morgan''s Vigil and Kargath both buy them as proof.', 1, 0, 4),
(7770015, 15, 0, 'Nazan''s Fel-Scorched Scale', 68107, 2, 1, 0, 90000, 1, 'A scale from Nazan, the fel dragon that guarded the Ramparts, still warm with fel fire.', 1, 0, 4),
(7770016, 15, 0, 'Freed Slave''s Woven Charm', 9852, 2, 1, 0, 90000, 1, 'A charm woven from marsh reeds by one of the slaves freed from the pens, made for the one who freed them.', 1, 0, 4),
(7770017, 15, 0, 'Auchenai Prayer Beads', 9853, 2, 1, 0, 100000, 1, 'Draenei prayer beads carried out of the Auchenai Crypts. The elders have blessed them again.', 1, 0, 4),
(7770018, 15, 0, 'Vial of Old Hillsbrad Sand', 37842, 2, 1, 0, 110000, 1, 'Sand from the timeway of Old Hillsbrad in a stoppered vial. It falls a little slower than it should.', 1, 0, 4),
(7770019, 15, 0, 'Arakkoa Sun-Feather', 11205, 2, 1, 0, 110000, 1, 'A long golden feather of the kind the arakkoa wore before the Sethekk turned to shadow.', 1, 0, 4),
(7770020, 15, 0, 'Infinite Dragon Scale', 20914, 2, 1, 0, 130000, 1, 'A black scale shed by one of the infinite dragonflight. It looks newer every time you look at it.', 1, 0, 4),
(7770021, 15, 0, 'Brass Coilfang Valve Wheel', 2322, 2, 1, 0, 130000, 1, 'A valve wheel taken from one of the Steamvault''s pumps. That pump won''t be turning again.', 1, 0, 4),
(7770022, 15, 0, 'Fragment of Kargath''s Bladefist', 15805, 2, 1, 0, 140000, 1, 'A broken piece of the blade Kargath wore in place of his hand.', 1, 0, 4),
(7770023, 15, 0, 'Arcane-Grown Bloom', 24693, 2, 1, 0, 140000, 1, 'A flower grown under the Botanica''s arcane lamps, preserved by Vargoth''s spell. It glows faintly violet.', 1, 0, 4),
(7770024, 15, 0, 'Millhouse''s Spare Spell Focus', 56465, 2, 1, 0, 140000, 1, 'A crystal focus Millhouse Manastorm insists he no longer needs. It hums smugly.', 1, 0, 4),
(7770025, 15, 0, 'Sun''s Reach Glass Rose', 50453, 2, 1, 0, 150000, 1, 'A rose of blown red glass, made by the artisans who returned to Sun''s Reach.', 1, 0, 4),
(7770026, 15, 0, 'Coldarra Ley Crystal', 39187, 2, 1, 0, 130000, 1, 'A crystal that grew where a ley line runs close to the surface of Coldarra. It has gone quiet since the Nexus fell silent.', 1, 0, 4),
(7770027, 15, 0, 'Nerubian Gemmed Chitin', 56645, 2, 1, 0, 130000, 1, 'A plate of nerubian chitin set with tiny gems, from the halls of the old kingdom.', 1, 0, 4),
(7770028, 15, 0, 'Twilight Cultist''s Signet', 26391, 2, 1, 0, 140000, 1, 'A signet ring taken from one of Jedoga Shadowseeker''s followers. Best sold quickly.', 1, 0, 4),
(7770029, 15, 0, 'Drakkari Bone Idol', 34138, 2, 1, 0, 140000, 1, 'A small idol of carved bone from Drak''Tharon''s shrines.', 1, 0, 4),
(7770030, 15, 0, 'Drakkari Tiki Mask', 32280, 2, 1, 0, 160000, 1, 'A carved and painted mask from the shrines of Gundrak. Bah''Kini has already catalogued it.', 1, 0, 4),
(7770031, 15, 0, 'Tribunal Record Tablet', 31287, 2, 1, 0, 170000, 1, 'A small stone tablet etched with the titans'' records, copied from the Tribunal of Ages. Brann has his own copy.', 1, 0, 4),
(7770032, 15, 0, 'Shard of Ymiron''s Crown', 15805, 2, 1, 0, 180000, 1, 'A fragment of the vrykul king''s iron crown.', 1, 0, 4),
(7770033, 15, 0, 'Shimmering Ley-Line Crystal', 31812, 2, 1, 0, 180000, 1, 'A crystal grown in the rings of the Oculus that glows when brought near a ley line.', 1, 0, 4),
(7770034, 15, 0, 'Loken''s Lightning-Scored Stone', 4718, 2, 1, 0, 180000, 1, 'A stone from the Halls of Lightning, burned with crackling patterns by Loken''s power.', 1, 0, 4),
(7770035, 15, 0, 'Chromie''s Pouch of Sand', 1285, 2, 1, 0, 180000, 1, 'A tiny pouch of sand from the timeways. Chromie insists it is perfectly ordinary sand. It isn''t.', 1, 0, 4),
(7770036, 15, 0, 'Black Knight''s Shattered Visor', 34221, 2, 1, 0, 200000, 1, 'The broken visor of the Black Knight. The Argent Crusade has examined it and declared it inert.', 1, 0, 4),
(7770037, 15, 0, 'Freed Soul Ember', 20901, 2, 1, 0, 200000, 1, 'A faint, warm light that drifted out of the Forge of Souls after the Devourer fell. It doesn''t fade.', 1, 0, 4),
(7770038, 15, 0, 'Shard of Frozen Halls Ice', 39928, 2, 1, 0, 220000, 1, 'A shard of ice from the Halls of Reflection. It never melts, and in the right light it shows faces.', 1, 0, 4),
(7770039, 15, 0, 'Zandalari Golden Idol', 2509, 3, 1, 0, 150000, 1, 'A small gold idol of a Zandalari loa, sent with the thanks of the Zandalar Tribe. Any collector would pay handsomely for it.', 1, 0, 4),
(7770040, 15, 0, 'Gilded Qiraji Scarab', 34159, 3, 1, 0, 150000, 1, 'A scarab of gold and obsidian from the ruins, the kind the Qiraji carried as a token of rank.', 1, 0, 4),
(7770041, 15, 0, 'Cooled Heart of Molten Stone', 4719, 3, 1, 0, 200000, 1, 'A fist-sized lump of rock from the Molten Core that has finally cooled. A faint warmth still lingers deep inside.', 1, 0, 4),
(7770042, 15, 0, 'Polished Scale of Onyxia', 68109, 3, 1, 0, 200000, 1, 'A scale from Onyxia''s hide, polished to a mirror shine. Nobles and armorers alike pay handsomely for them.', 1, 0, 4),
(7770043, 15, 0, 'Shard of Chromatic Scale', 20893, 3, 1, 0, 300000, 1, 'A scale from one of Nefarian''s chromatic drakes, shifting through five colours in the light.', 1, 0, 4),
(7770044, 15, 0, 'Ahn''Qiraj Obsidian Shard', 15805, 3, 1, 0, 400000, 1, 'A sliver of the dark stone that lined the Old God''s chamber, cleansed by the bronze dragonflight.', 1, 0, 4),
(7770045, 15, 0, 'Dulled Necropolis Shard', 9110, 3, 1, 0, 500000, 1, 'A shard of the dark stone of Naxxramas, drained of its unholy power. The Argent Dawn has declared it safe to sell.', 1, 0, 4),
(7770046, 15, 0, 'Starlit Glass from the Observatory', 44923, 3, 1, 0, 400000, 1, 'A curved pane of glass from Karazhan''s observatory. Look through it at night, and the stars seem closer.', 1, 0, 4),
(7770047, 15, 0, 'Gronn Tooth Fragment', 38648, 3, 1, 0, 400000, 1, 'A fragment of one of Gruul''s teeth, as big as a dwarf''s fist.', 1, 0, 4),
(7770048, 15, 0, 'Link of Magtheridon''s Chains', 23145, 3, 1, 0, 450000, 1, 'A link from the chains that held the pit lord beneath Hellfire Citadel, scorched black.', 1, 0, 4),
(7770049, 15, 0, 'Amani Gold Figurine', 39920, 3, 1, 0, 500000, 1, 'A heavy gold figurine from Zul''Aman''s treasury. Harrison Jones swears it was ''surplus to the collection''.', 1, 0, 4),
(7770050, 15, 0, 'Vashj''s Lustrous Pearl', 54312, 3, 1, 0, 600000, 1, 'A large pearl from Serpentshrine Cavern, lustrous and faintly cold. The naga prized them above gold.', 1, 0, 4),
(7770051, 15, 0, 'Tempest Keep Crystal Shard', 39938, 3, 1, 0, 600000, 1, 'A shard of naaru crystal from the Eye, softly humming.', 1, 0, 4),
(7770052, 15, 0, 'Sliver of Nordrassil''s Bark', 1500, 3, 1, 0, 750000, 1, 'A sliver of bark from the World Tree as it stood on the day of the battle. It smells of rain and leaves.', 1, 0, 4),
(7770053, 15, 0, 'Karabor Prayer Bell', 17911, 3, 1, 0, 900000, 1, 'A small silver bell from the temple''s sanctuary, older than the Black Temple''s dark years. The Ashtongue gave it freely.', 1, 0, 4),
(7770054, 15, 0, 'Sunwell Glass Shard', 44925, 3, 1, 0, 1000000, 1, 'A shard of golden glass from the Sunwell Plateau, warm with the restored Sunwell''s light.', 1, 0, 4),
(7770055, 15, 0, 'Titan-Forged Stone Chip', 4721, 3, 1, 0, 500000, 1, 'A chip of rune-carved stone from one of the Vault''s watchers. Archaeologists in Ironforge and Silvermoon would both bid for it.', 1, 0, 4),
(7770056, 15, 0, 'Naxxramas Rune-Stone', 24677, 3, 1, 0, 750000, 1, 'A rune-carved block from the necropolis''s outer wall, drained of its power.', 1, 0, 4),
(7770057, 15, 0, 'Twilight Dragon Eggshell', 44923, 3, 1, 0, 750000, 1, 'A fragment of a destroyed twilight dragon egg, dark purple and cold as ice.', 1, 0, 4),
(7770058, 15, 0, 'Onyxian Scale Pendant', 48511, 3, 1, 0, 750000, 1, 'A pendant carved from one of Onyxia''s scales, set in silver by a Theramore jeweler (or a goblin in Brackenwall).', 1, 0, 4),
(7770059, 15, 0, 'Azure Spellweaver''s Prism', 44929, 3, 1, 0, 850000, 1, 'A prism of blue crystal from the Eye of Eternity. Light passing through it shows the shape of the ley lines.', 1, 0, 4),
(7770060, 15, 0, 'Titan Keeper''s Rune', 35465, 3, 1, 0, 1100000, 1, 'A rune-stone from the halls of Ulduar, still faintly glowing with the keepers'' power.', 1, 0, 4),
(7770061, 15, 0, 'Coliseum Champion''s Laurel', 14439, 3, 1, 0, 1200000, 1, 'A laurel wreath of gilded silver, given to the champions of the Coliseum.', 1, 0, 4),
(7770062, 15, 0, 'Frozen Throne Ice Shard', 31812, 3, 1, 0, 2000000, 1, 'A shard of ice from the summit of Icecrown Citadel that refuses to melt.', 1, 0, 4),
(7770063, 15, 0, 'Ruby Sanctum Ember', 1263, 3, 1, 0, 1500000, 1, 'An ember from the Ruby Sanctum''s burned grove, held in a ruby glass globe. It glows warmly and never dies out.', 1, 0, 4),
(7770064, 15, 0, 'Melrache''s Signet Ring', 28682, 2, 1, 0, 4500, 1, 'A heavy silver ring bearing the flame of the Scarlet Crusade. The Executor has no use for Scarlet trinkets, but any merchant will melt it down.', 1, 0, 4),
(7770065, 15, 0, 'Inert Ley Crystal', 2516, 2, 1, 0, 10000, 1, 'A cloudy crystal taken from the stilled ley node at Ambermill. Whatever power it held has drained away.', 1, 0, 4),
(7770066, 15, 0, 'Dun Garok Signal Horn', 956, 2, 1, 0, 17500, 1, 'A dented dwarven horn that once called the mountaineers of Dun Garok to arms. It will not be sounded again.', 1, 0, 4),
(7770067, 15, 0, 'Raven Hill Grave Lily', 19498, 2, 1, 0, 20000, 1, 'A violet lily that has begun to grow on the graves of Raven Hill. The herbalists of Darkshire say it never bloomed there while Morbent Fel lived.', 1, 0, 4),
(7770068, 15, 0, 'Boulderfist Tusk Ring', 23780, 2, 1, 0, 30000, 1, 'An ogre lord''s ring carved from a boar tusk, far too big for any orc finger. The grunts drew lots for it, and you won.', 1, 0, 4),
(7770069, 15, 0, 'Vardus Family Seal', 17724, 2, 1, 0, 30000, 1, 'A wax-seal stamp bearing the crest of a minor Alterac house. The house is gone, but a collector in Stormwind might still want the seal.', 1, 0, 4),
(7770070, 15, 0, 'Carved Driftwood Wagon', 7914, 2, 1, 0, 30000, 1, 'A piece of sun-bleached driftwood that Watcher Biggs whittled into a little wagon while waiting for repairs. Surprisingly well made.', 1, 0, 4),
(7770071, 15, 0, 'Cooled Lethlor Obsidian', 961, 2, 1, 0, 50000, 1, 'A shard of black glass from the floor of Lethlor Ravine, formed where dragonfire melted the rock. It has finally gone cold.', 1, 0, 4),
(7770072, 15, 0, 'Sharpbeak''s Molted Feather', 19529, 2, 1, 0, 50000, 1, 'A long beautiful feather shed by the young gryphon you saved. Wildhammer fletchers would pay well for it, though Talonaxe hopes you''ll keep it.', 1, 0, 4),
(7770073, 15, 0, 'Revantusk Carved Tusk', 13081, 2, 1, 0, 50000, 1, 'A boar tusk carved with the story of Elder Torntusk''s rescue. Traders in Orgrimmar buy every one the Revantusk make.', 1, 0, 4),
(7770074, 15, 0, 'Dreadmaul Ember Stone', 4716, 2, 1, 0, 60000, 1, 'A smooth stone from the slopes of Dreadmaul Rock that stays warm for days. Ogres carry them as charms, and merchants sell them as hand-warmers.', 1, 0, 4),
(7770075, 15, 0, 'Darrowshire Pressed Flower', 24689, 2, 1, 0, 55000, 1, 'A small blue flower pressed between the pages of an old Darrowshire family book. Carlin found several there.', 1, 0, 4),
(7770076, 15, 0, 'Pale Blasted Lands Sprout', 2948, 2, 1, 0, 70000, 1, 'A tiny grey-green sprout in a pinch of red dust, found near one of the binding stones. Nothing has grown there in years.', 1, 0, 4),
(7770077, 15, 0, 'Untainted Ear of Wheat', 19492, 2, 1, 0, 60000, 1, 'A single ear of wheat grown near Felstone Farm, free of any trace of plague. The Argent Dawn is saving the seeds, and this one was spare.', 1, 0, 4),
(7770078, 15, 0, 'Blackwood Furbolg Charm', 18309, 2, 1, 0, 6000, 1, 'A charm of braided grass and a polished river stone, left on the road near Auberdine by one of the Blackwood furbolgs. Perhaps it was meant as thanks.', 1, 0, 4),
(7770079, 15, 0, 'Stonetalon Pine Seedling', 2025, 2, 1, 0, 15000, 1, 'A young pine in a clay pot, dug from a slope where the shredders have stopped. Druids and gardeners will pay for it.', 1, 0, 4),
(7770080, 15, 0, 'Freewind Wind Chime', 9852, 2, 1, 0, 15000, 1, 'A small chime of bone and feathers like those that hang at Freewind Post. It rings whenever the wind changes. Kanati made this one for you.', 1, 0, 4),
(7770081, 15, 0, 'Shady Rest Inn Tankard', 18101, 2, 1, 0, 20000, 1, 'A pewter tankard pulled from the ashes of the Shady Rest Inn, still black with soot. The innkeeper won''t be needing it.', 1, 0, 4),
(7770082, 15, 0, 'Centaur Clan Bead', 9854, 2, 1, 0, 30000, 1, 'A carved stone bead on a hide cord, given by the clan you fought for as a sign of friendship. Traders know its worth.', 1, 0, 4),
(7770083, 15, 0, 'High Wilderness Fern', 1646, 2, 1, 0, 40000, 1, 'A frond of a rare fern growing among the ruins where the Gordunni once camped. Alchemists prize its scent.', 1, 0, 4),
(7770084, 15, 0, 'Moonlit Azshara Blossom', 24692, 2, 1, 0, 40000, 1, 'A pale blossom that opens only at night, found in a glade the satyr no longer haunt.', 1, 0, 4),
(7770085, 15, 0, 'Lar''korwi''s Fang', 2598, 2, 1, 0, 60000, 1, 'A huge yellowed fang from the beast you hunted. Torwa says a hunter should keep such things, but a trader will pay for it.', 1, 0, 4),
(7770086, 15, 0, 'Winterfall Spirit Bead', 35359, 2, 1, 0, 70000, 1, 'A carved wooden bead from a Winterfall necklace, found near their camp and washed clean of corruption.', 1, 0, 4),
(7770087, 15, 0, 'Cenarion Desert Rose', 942, 2, 1, 0, 70000, 1, 'A hardy desert rose grown by the druids of Cenarion Hold, a sign that even Silithus can be coaxed into bloom.', 1, 0, 4),
(7770088, 15, 0, 'Stillpine Carved Totem', 53133, 2, 1, 0, 4500, 1, 'A small wooden totem the Stillpine carve for friends. Merchants in the Exodar find them charming.', 1, 0, 4),
(7770089, 15, 0, 'Cleansed Exodar Crystal Shard', 44929, 2, 1, 0, 8000, 1, 'A shard of the Exodar''s crystal hull found on Bloodmyst Isle. Once stained red, it has turned pale blue again.', 1, 0, 4),
(7770090, 15, 0, 'Quel''Thalas Orchid', 19495, 2, 1, 0, 8000, 1, 'Once, such flowers grew throughout southern Quel''Thalas, but they vanished completely many years ago after the Scourge cursed these lands. This blossom appears fresh.', 1, 0, 4),
(7770091, 15, 0, 'Shard of the Rune of Spite', 20220, 2, 1, 0, 90000, 1, 'A cracked fragment of the rune that powered the Legion''s portal, now dead stone. The Honor Hold quartermaster buys them as souvenirs.', 1, 0, 4),
(7770092, 15, 0, 'Smooth Raven Stone', 24677, 2, 1, 0, 100000, 1, 'A polished black stone from the streams near Raven''s Wood. The Boulder''mok carried them as lucky charms. It didn''t help.', 1, 0, 4),
(7770093, 15, 0, 'Kirin''Var Memorial Candle', 1474, 2, 1, 0, 110000, 1, 'A silver candle like those the spirits of Kirin''Var light for their fallen. It burns with a faint arcane glow.', 1, 0, 4),
(7770094, 15, 0, 'Cooled Felsteel Slag', 34364, 2, 1, 0, 120000, 1, 'A lump of slag from a Legion forge, finally cool enough to hold. Smiths use such pieces to test their furnaces.', 1, 0, 4),
(7770095, 15, 0, 'Lordaeron Noble''s Signet', 31498, 2, 1, 0, 140000, 1, 'A gold signet ring recovered from Wintergarde Crypt. The family it belonged to has no living heirs.', 1, 0, 4),
(7770096, 15, 0, 'Rune-Etched Iron Shard', 42561, 2, 1, 0, 150000, 1, 'A fragment of the Anvil, the Iron Thane''s guardian construct. The runes on it have gone dark.', 1, 0, 4),
(7770097, 15, 0, 'Lifebloom Blossom', 52249, 2, 1, 0, 180000, 1, 'A blossom from the Avalanche, where the land has begun to heal after the Etymidian''s fury.', 1, 0, 4),
(7770098, 15, 0, 'Thane Ufrang''s Drinking Horn', 13122, 2, 1, 0, 200000, 1, 'The thane''s drinking horn, carved from a proto-drake''s horn. The Ebon Blade has no use for it.', 1, 0, 4);
